#!/usr/bin/env bash
# Writes config.js from the TMDB_API_KEY env var without ever echoing the value.
# TMDB v3 API keys (or v4 read-access tokens) are read-only and intended for client-side use.
set -euo pipefail
cd "$(dirname "$0")/.."
python3 - <<'PY'
import os, json
k = os.environ.get("TMDB_API_KEY", "").strip()
open("config.js", "w").write(
  "/* Generated by scripts/gen-config.sh from $TMDB_API_KEY. TMDB read key: public by design. */\n"
  "window.REELPICK_CONFIG = " + json.dumps({"tmdbKey": k}) + ";\n")
print("config.js written:", "key present" if k else "EMPTY (offline fallback)")
PY
